static std::array<int,3> parts(const std::string& v){std::array<int,3> p{};if(!std::regex_match(v,std::regex("[0-9]{1,4}\\.[0-9]{1,4}\\.[0-9]{1,4}")))throw std::runtime_error("version");std::istringstream s(v);char dot;s>>p[0]>>dot>>p[1]>>dot>>p[2];return p;}
bool newerVersion(const std::string& a,const std::string& b){try{return parts(a)>parts(b);}catch(...){return false;}}
Update selectUpdate(const Json& r,const std::string& current){Update u;if(!r.is_object()||r.value("draft",true)||r.value("prerelease",true))return u;auto tag=r.value("tag_name",std::string{});if(tag.size()<2||tag[0]!='v'||!newerVersion(tag.substr(1),current))return u;auto expected="https://github.com/tab16360/flowcat-windows/releases/download/"+tag+"/FlowCat-Windows-x64-Setup.exe";
 if(!r.contains("assets")||!r["assets"].is_array())return u;for(auto& a:r["assets"]){if(a.value("name",std::string{})!="FlowCat-Windows-x64-Setup.exe"||a.value("browser_download_url",std::string{})!=expected)continue;auto digest=a.value("digest",std::string{});auto size=a.value("size",uint64_t{});if(!std::regex_match(digest,std::regex("sha256:[a-fA-F0-9]{64}"))||!size||size>64*1024*1024)return u;u={tag.substr(1),expected,digest.substr(7),size,true};return u;}return u;}
struct Http {HINTERNET h=nullptr;~Http(){if(h)WinHttpCloseHandle(h);}operator HINTERNET()const{return h;}};
static std::vector<BYTE> get(std::wstring url,size_t limit){
 Http session{WinHttpOpen(L"FlowCatWindows/0.2.0",WINHTTP_ACCESS_TYPE_AUTOMATIC_PROXY,WINHTTP_NO_PROXY_NAME,WINHTTP_NO_PROXY_BYPASS,0)};if(!session.h)throw std::runtime_error("network");WinHttpSetTimeouts(session,5000,10000,15000,15000);
 for(int redirect=0;redirect<6;++redirect){URL_COMPONENTS c{};c.dwStructSize=sizeof(c);c.dwHostNameLength=c.dwUrlPathLength=c.dwExtraInfoLength=DWORD(-1);if(!WinHttpCrackUrl(url.c_str(),0,0,&c)||c.nScheme!=INTERNET_SCHEME_HTTPS)throw std::runtime_error("url");std::wstring host(c.lpszHostName,c.dwHostNameLength),path(c.lpszUrlPath,c.dwUrlPathLength);if(c.dwExtraInfoLength)path.append(c.lpszExtraInfo,c.dwExtraInfoLength);
  if(host!=L"api.github.com"&&host!=L"github.com"&&host!=L"release-assets.githubusercontent.com"&&host!=L"objects.githubusercontent.com")throw std::runtime_error("host");
  Http connection{WinHttpConnect(session,host.c_str(),c.nPort,0)};Http request{WinHttpOpenRequest(connection,L"GET",path.c_str(),nullptr,WINHTTP_NO_REFERER,WINHTTP_DEFAULT_ACCEPT_TYPES,WINHTTP_FLAG_SECURE)};if(!connection.h||!request.h)throw std::runtime_error("network");DWORD disable=WINHTTP_DISABLE_REDIRECTS;WinHttpSetOption(request,WINHTTP_OPTION_DISABLE_FEATURE,&disable,sizeof(disable));if(!WinHttpSendRequest(request,host==L"api.github.com"?L"Accept: application/vnd.github+json\r\n":L"Accept: application/octet-stream\r\n",DWORD(-1L),WINHTTP_NO_REQUEST_DATA,0,0,0)||!WinHttpReceiveResponse(request,nullptr))throw std::runtime_error("network");DWORD status=0,size=sizeof(status);WinHttpQueryHeaders(request,WINHTTP_QUERY_STATUS_CODE|WINHTTP_QUERY_FLAG_NUMBER,WINHTTP_HEADER_NAME_BY_INDEX,&status,&size,WINHTTP_NO_HEADER_INDEX);
  if(status>=300&&status<400){DWORD bytes=0;WinHttpQueryHeaders(request,WINHTTP_QUERY_LOCATION,WINHTTP_HEADER_NAME_BY_INDEX,nullptr,&bytes,WINHTTP_NO_HEADER_INDEX);if(!bytes||bytes>32768)throw std::runtime_error("redirect");std::vector<wchar_t> location(bytes/2+1);if(!WinHttpQueryHeaders(request,WINHTTP_QUERY_LOCATION,WINHTTP_HEADER_NAME_BY_INDEX,location.data(),&bytes,WINHTTP_NO_HEADER_INDEX))throw std::runtime_error("redirect");url=location.data();continue;}
  if(status!=200)throw std::runtime_error("http "+std::to_string(status));std::vector<BYTE> result;BYTE buffer[65536];DWORD count=0;while(WinHttpReadData(request,buffer,sizeof(buffer),&count)&&count){if(result.size()+count>limit)throw std::runtime_error("size");result.insert(result.end(),buffer,buffer+count);}return result;
 }throw std::runtime_error("redirect");
}
Update checkUpdate(const std::string& current){auto bytes=get(L"https://api.github.com/repos/tab16360/flowcat-windows/releases/latest",2*1024*1024);return selectUpdate(Json::parse(bytes.begin(),bytes.end()),current);}
static std::string sha256(const std::vector<BYTE>& bytes){BCRYPT_ALG_HANDLE algorithm=nullptr;BCRYPT_HASH_HANDLE hash=nullptr;DWORD size=0,objectSize=0;if(BCryptOpenAlgorithmProvider(&algorithm,BCRYPT_SHA256_ALGORITHM,nullptr,0)<0)throw std::runtime_error("hash");BCryptGetProperty(algorithm,BCRYPT_OBJECT_LENGTH,reinterpret_cast<BYTE*>(&objectSize),sizeof(objectSize),&size,0);std::vector<BYTE> object(objectSize);BYTE digest[32];bool good=BCryptCreateHash(algorithm,&hash,object.data(),objectSize,nullptr,0,0)>=0&&BCryptHashData(hash,const_cast<BYTE*>(bytes.data()),static_cast<ULONG>(bytes.size()),0)>=0&&BCryptFinishHash(hash,digest,sizeof(digest),0)>=0;if(hash)BCryptDestroyHash(hash);BCryptCloseAlgorithmProvider(algorithm,0);if(!good)throw std::runtime_error("hash");std::ostringstream out;for(auto b:digest)out<<std::hex<<std::setw(2)<<std::setfill('0')<<static_cast<int>(b);return out.str();}
std::wstring downloadUpdate(const Update& update){if(!update.available)throw std::runtime_error("update");auto data=get(wide(update.url),static_cast<size_t>(update.size));auto digest=update.digest;std::transform(digest.begin(),digest.end(),digest.begin(),[](unsigned char c){return static_cast<char>(::tolower(c));});if(data.size()!=update.size||sha256(data)!=digest)throw std::runtime_error("digest");
 PWSTR base=nullptr;if(FAILED(SHGetKnownFolderPath(FOLDERID_LocalAppData,0,nullptr,&base)))throw std::runtime_error("cache");auto directory=std::filesystem::path(base)/L"FlowCatWindows"/L"updates";CoTaskMemFree(base);GUID guid;CoCreateGuid(&guid);wchar_t id[64];StringFromGUID2(guid,id,64);directory/=id;std::filesystem::create_directories(directory);auto path=directory/L"FlowCat-Windows-x64-Setup.exe";std::ofstream f(path,std::ios::binary);f.write(reinterpret_cast<const char*>(data.data()),static_cast<std::streamsize>(data.size()));f.close();if(!f)throw std::runtime_error("cache");
 DWORD dummy=0,length=GetFileVersionInfoSizeW(path.c_str(),&dummy);std::vector<BYTE> version(length);VS_FIXEDFILEINFO* info=nullptr;UINT infoLength=0;auto expected=parts(update.version);if(!length||!GetFileVersionInfoW(path.c_str(),0,length,version.data())||!VerQueryValueW(version.data(),L"\\",reinterpret_cast<void**>(&info),&infoLength)||infoLength<sizeof(*info)||HIWORD(info->dwProductVersionMS)!=expected[0]||LOWORD(info->dwProductVersionMS)!=expected[1]||HIWORD(info->dwProductVersionLS)!=expected[2]){DeleteFileW(path.c_str());throw std::runtime_error("package-version");}return path;
}
bool launchUpdate(const std::wstring& path,const Update& update){HANDLE file=CreateFileW(path.c_str(),GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);if(file==INVALID_HANDLE_VALUE)return false;LARGE_INTEGER size{};if(!GetFileSizeEx(file,&size)||size.QuadPart!=static_cast<LONGLONG>(update.size)||update.size>64*1024*1024){CloseHandle(file);return false;}std::vector<BYTE> verified(static_cast<size_t>(update.size));DWORD count=0;if(!ReadFile(file,verified.data(),static_cast<DWORD>(verified.size()),&count,nullptr)||count!=verified.size()){CloseHandle(file);return false;}auto expected=update.digest;std::transform(expected.begin(),expected.end(),expected.begin(),[](unsigned char c){return static_cast<char>(::tolower(c));});std::string actual;try{actual=sha256(verified);}catch(...){CloseHandle(file);return false;}if(actual!=expected){CloseHandle(file);return false;}SHELLEXECUTEINFOW s{sizeof(s)};s.fMask=SEE_MASK_NOCLOSEPROCESS;s.lpVerb=L"runas";s.lpFile=path.c_str();s.lpParameters=L"/VERYSILENT /SUPPRESSMSGBOXES /NORESTART /SP- /UPDATE=1";s.nShow=SW_SHOW;if(!ShellExecuteExW(&s)){CloseHandle(file);return false;}CloseHandle(file);if(s.hProcess)CloseHandle(s.hProcess);return true;}
